WITH flattened AS (SELECT id, log_ts, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, value) SELECT CASE WHEN status_code >= 400 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, CASE WHEN latency_ms >= 1898 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, BIT_AND(status_code) AS status_code_bit_and, MAX(status_code) FILTER (WHERE k = 'trace') AS trace_max_status_code, SIZE(COLLECT_SET(k)) AS num_ks FROM flattened GROUP BY status_code_tier, latency_ms_tier
